DO $$ DECLARE name text; def text; BEGIN FOREACH name IN ARRAY ARRAY['public.complaint_details_guard()','public.edit_complaint_details(uuid,uuid,jsonb,text)'] LOOP SELECT pg_get_functiondef(name::regprocedure) INTO def; def:=replace(def,'OLD.assigned_to=auth.uid()','coalesce(OLD.assigned_to=auth.uid(),false)'); def:=replace(def,'c.assigned_to=auth.uid()','coalesce(c.assigned_to=auth.uid(),false)'); EXECUTE def; END LOOP; END $$;